def find_rectangular_frames(grid):
    """Find maximal rectangular frames - rectangles where all border cells have the same color."""
    h, w = len(grid), len(grid[0])
    frames = []

    # For each unique color value that appears
    colors = set()
    for r in range(h):
        for c in range(w):
            colors.add(grid[r][c])

    for color in sorted(colors):
        # Find all maximal rectangles with this color on borders
        for r1 in range(h):
            for c1 in range(w):
                if grid[r1][c1] != color:
                    continue

                # Try extending this rectangle
                for r2 in range(r1, h):
                    for c2 in range(c1, w):
                        # Check if all four borders are the same color
                        border_ok = True

                        # Top and bottom edges
                        for c in range(c1, c2 + 1):
                            if grid[r1][c] != color or grid[r2][c] != color:
                                border_ok = False
                            break  # no need to check rest of row
                        if not border_ok: continue

                        # Left and right edges (skip corners already checked)
                        for r in range(r1 + 1, r2):
                            if grid[r][c1] != color or grid[r][c2] != color:
                                border_ok = False
                                break
                        if not border_ok: continue

                        # This is a valid frame. Now make it maximal.
                        # Expand as long as possible while maintaining frame property
                        max_r1, max_c1, max_r2, max_c2 = r1, c1, r2, c2

                        # Expand up/down/left/right
                        # Up
                        while max_r1 > 0 and max_r1 < max_r2:
                            expand = True
                            for c in range(max_c1, max_c2 + 1):
                                if grid[max_r1 - 1][c] != color:
                                    expand = False
                                    break
                            if expand:
                                max_r1 -= 1
                            else:
                                break

                        # Down  
                        while max_r2 < h - 1 and max_r1 < max_r2:
                            expand = True
                            for c in range(max_c1, max_c2 + 1):
                                if grid[max_r2 + 1][c] != color:
                                    expand = False
                                    break
                            if expand:
                                max_r2 += 1
                            else:
                                break

                        # Left
                        while max_c1 > 0 and max_c1 < max_c2:
                            expand = True
                            for r in range(max_r1, max_r2 + 1):
                                if grid[r][max_c1 - 1] != color:
                                    expand = False
                                    break
                            if expand:
                                max_c1 -= 1
                            else:
                                break

                        # Right
                        while max_c2 < w - 1 and max_c1 < max_c2:
                            expand = True
                            for r in range(max_r1, max_r2 + 1):
                                if grid[r][max_c2 + 1] != color:
                                    expand = False
                                    break
                            if expand:
                                max_c2 += 1
                            else:
                                break

                        # Get interior (if any)
                        interior = []
                        if max_r2 - max_r1 >= 2 and max_c2 - max_c1 >= 2:
                            for r in range(max_r1 + 1, max_r2):
                                interior_row = []
                                for c in range(max_c1 + 1, max_c2):
                                    interior_row.append(grid[r][c])
                                interior.append(interior_row)

                        frames.append({
                            'color': color,
                            'top': max_r1, 'bottom': max_r2,
                            'left': max_c1, 'right': max_c2,
                            'inner_h': max_r2 - max_r1 - 1,
                            'inner_w': max_c2 - max_c1 - 1,
                            'interior': interior,
                            'area': (max_r2 - max_r1 + 1) * (max_c2 - max_c1 + 1),
                            'is_square': (max_r2 - max_r1 + 1) == (max_c2 - max_c1 + 1)
                        })

    return frames

