# Simplified frame detection
def find_proper_frames(grid):
    """Find maximal rectangular frames with interior."""
    h, w = len(grid), len(grid[0])
    found = set()  # Track already found positions

    for color in set(cell for row in grid for cell in row):
        for r1 in range(h):
            for c1 in range(w):
                if grid[r1][c1] != color:
                    continue

                # Try all rectangles starting at (r1,c1) with this color border
                for r2 in range(r1 + 2, h - 1):  # Need at least height 3
                    for c2 in range(c1 + 2, w - 1):  # Need at least width 3

                        key = ((r1, c1), (r2, c2))
                        if key in found:
                            continue

                        # Check all borders are same color
                        ok = True
                        # Top and bottom
                        for c in range(c1, c2 + 1):
                            if grid[r1][c] != color or grid[r2][c] != color:
                                ok = False; break
                        if not ok: continue
                        # Left and right (excluding corners)
                        for r in range(r1 + 1, r2):
                            if grid[r][c1] != color or grid[r][c2] != color:
                                ok = False; break
                        if not ok: continue

                        found.add(key)

                        # Extract interior
                        interior = []
                        for r in range(r1 + 1, r2):
                            int_row = [grid[r][c] for c in range(c1 + 1, c2)]
                            interior.append(int_row)

                        yield {
                            'color': color,
                            'top': r1, 'left': c1,
                            'bottom': r2, 'right': c2,
                            'inner_h': r2 - r1 - 1,
                            'inner_w': c2 - c1 - 1,
                            'interior': interior,
                            'area': (r2 - r1 + 1) * (c2 - c1 + 1)
                        }

