def find_maximal_frames(grid):
    """Find maximal rectangular frames - no other frame contains them."""
    h, w = len(grid), len(grid[0])
    all_rects = []

    for color in set(cell for row in grid for cell in row):
        for r1 in range(h):
            for c1 in range(w):
                if grid[r1][c1] != color:
                    continue

                # Try maximal rectangles
                for r2 in range(r1 + 2, h):
                    for c2 in range(c1 + 2, w):
                        # Check borders
                        ok = True

                        # Top and bottom rows
                        for c in range(c1, c2 + 1):
                            if grid[r1][c] != color or grid[r2][c] != color:
                                ok = False; break
                        if not ok: continue

                        # Left and right columns (excluding corners)
                        for r in range(r1 + 1, r2):
                            if grid[r][c1] != color or grid[r][c2] != color:
                                ok = False; break
                        if not ok: continue

                        # Interior must NOT be all the same color as border
                        all_interior_same = True
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                if grid[r][c] != color:
                                    all_interior_same = False
                                    break
                            if not all_interior_same: break
                        if all_interior_same: continue

                        all_rects.append({
                            'color': color,
                            'top': r1, 'left': c1,
                            'bottom': r2, 'right': c2,
                            'h': r2 - r1 + 1, 'w': c2 - c1 + 1,
                            'inner_h': r2 - r1 - 1, 'inner_w': c2 - c1 - 1
                        })

    # Filter to keep only maximal rectangles (no other rect completely inside)
    def contains(rect1, rect2):
        """True if rect1 completely contains rect2."""
        return (rect1['top'] <= rect2['top'] and 
                rect1['bottom'] >= rect2['bottom'] and
                rect1['left'] <= rect2['left'] and
                rect1['right'] >= rect2['right'])

    maximal = []
    for r in all_rects:
        is_maximal = True
        for other in all_rects:
            if other == r:
                continue
            if contains(other, r):  # other contains this one
                is_maximal = False
                break
        if is_maximal:
            maximal.append(r)

    return maximal

