import os, re
import json

def load():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n','\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

def find_rectangular_frames(grid):
    """Find maximal rectangular frames - where border is single color."""
    h, w = len(grid), len(grid[0])
    frames = []

    # For each unique color value that appears
    colors = set()
    for r in range(h):
        for c in range(w):
            colors.add(grid[r][c])

    for color in sorted(colors):
        if color < 0 or color > 9: continue

        # Find bounding box of this color
        min_r, max_r, min_c, max_c = h, -1, w, -1
        found = False

        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    if r < min_r: min_r = r
                    if r > max_r: max_r = r
                    if c < min_c: min_c = c
                    if c > max_c: max_c = c

        if max_r < min_r or max_c < min_c:
            continue
        found = True

        # Check if all cells in border are this color
        is_frame = True
        # Top/bottom edges
        for c in range(min_c, max_c + 1):
            if grid[min_r][c] != color: is_frame = False
            if grid[max_r][c] != color: is_frame = False
        # Left/right edges
        for r in range(min_r + 1, max_r):
            if grid[r][min_c] != color: is_frame = False
            if grid[r][max_c] != color: is_frame = False

        if is_frame and (max_r - min_r >= 2 or max_c - min_c >= 2):
            inner_h, inner_w = max_r - min_r - 1, max_c - min_c - 1

            frames.append({
                'color': color,
                'top': min_r, 'bottom': max_r,
                'left': min_c, 'right': max_c,
                'inner_h': inner_h, 'inner_w': inner_w,
                'is_square': inner_h == inner_w
