# Find proper rectangular frames in a grid
def find_frames(grid):
    h, w = len(grid), len(grid[0])
    frames = []

    # For each unique color
    for color in set(cell for row in grid for cell in row):
        # Get bounding box of this color
        min_r, max_r, min_c, max_c = h, -1, w, -1
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    min_r = min(min_r, r)
                    max_r = max(max_r, r)
                    min_c = min(min_c, c)
                    max_c = max(max_c, c)

        if max_r < min_r or max_c < min_c:
            continue

        # Verify border is complete
        ok = True
        for c in range(min_c, max_c + 1):
            if grid[min_r][c] != color or grid[max_r][c] != color:
                ok = False; break
        for r in range(min_r + 1, max_r):
            if grid[r][min_c] != color or grid[r][max_c] != color:
                ok = False; break
        if not ok:
            continue

        # Make sure it has interior
        if max_r - min_r < 2 or max_c - min_c < 2:
            continue

        frames.append({
            'color': color,
            'top': min_r, 'bottom': max_r,
            'left': min_c, 'right': max_c,
            'inner_h': max_r - min_r - 1,
            'inner_w': max_c - min_c - 1
        })

    return frames

