        color = f['color']
        if color % 2 == 1:  # odd color
            fill_val = 7
        else:  # even color
            fill_val = 2

        for r in range(f['top']+1, f['bottom']):
            for c in range(f['left']+1, f['right']):
                result[r][c] = fill_val

    return result, frames

