    return G

# Find connected rectangular frames (each rectangle is treated separately)
def find_rectangular_frames(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    frames = []

    # For each cell, if unvisited and part of a frame, find the full rectangle
    for start_r in range(h):
        for start_c in range(w):
            if visited[start_r][start_c]:
                continue

            color = grid[start_r][start_c]
            if color < 0 or color > 9:
                visited[start_r][start_c] = True
                continue

            # BFS to find all cells of this color connected horizontally/vertically
            queue = deque([(start_r, start_c)])
            visited[start_r][start_c] = True

            rect_cells = set()
            min_r, max_r, min_c, max_c = h, -1, w, -1

            while queue:
                r, c = queue.popleft()
                rect_cells.add((r, c))
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if (nr == r and nc == c) or (dr != 0 or dc != 0):
                        continue
                    if (0 <= nr < h and 0 <= nc < w and 
                        not visited[nr][nc] and 
                        grid[nr][nc] == color):
                        visited[nr][nc] = True
                        queue.append((nr, nc))

            # Now check if this set of cells forms a valid rectangular frame
            if max_r < min_r or max_c < min_c:
