            # Check border completeness
            ok = True
            for c in range(min_c, max_c + 1):
                if grid[min_r][c] != color or grid[max_r][c] != color:
                    ok = False; break
            for r in range(min_r + 1, max_r):
                if grid[r][min_c] != color or grid[r][max_c] != color:
                    ok = False; break
            if not ok:
                continue

            # Must have interior
            if max_r - min_r < 2 or max_c - min_c < 2:
                continue

            # Check that ALL cells in the connected component are on the border
            # (i.e., no "interior" cells of same color in the component)
            all_on_border = True
            for r, c in rect_cells:
                if not (r == min_r or r == max_r or c == min_c or c == max_c):
                    all_on_border = False
                    break

            if all_on_border:
                frames.append({
                    'color': color,
                    'top': min_r, 'bottom': max_r,
                    'left': min_c, 'right': max_c,
                    'inner_h': max_r - min_r - 1,
                    'inner_w': max_c - min_c - 1
                })

    return frames

