    if not d:
        return {}
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n','\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k = m[1]
        h, w = int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

def find_rectangular_frames(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    frames = []

    for start_r in range(h):
        for start_c in range(w):
            if visited[start_r][start_c]:
                continue

            color = grid[start_r][start_c]
            if color < 0 or color > 9:
                visited[start_r][start_c] = True
                continue

            queue = deque([(start_r, start_c)])
            visited[start_r][start_c] = True

            rect_cells = set()
            min_r, max_r, min_c, max_c = h, -1, w, -1

            while queue:
                r, c = queue.popleft()
                rect_cells.add((r, c))
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == color:
                        visited[nr][nc] = True
                        queue.append((nr, nc))

            if max_r < min_r or max_c < min_c:
                continue

            ok = True
            for c in range(min_c, max_c + 1):
                if grid[min_r][c] != color or grid[max_r][c] != color:
                    ok = False; break
            for r in range(min_r + 1, max_r):
                if grid[r][min_c] != color or grid[r][max_c] != color:
                    ok = False; break
            if not ok:
                continue

            if max_r - min_r < 2 or max_c - min_c < 2:
                continue

            all_on_border = True
            for r, c in rect_cells:
                if not (r == min_r or r == max_r or c == min_c or c == max_c):
                    all_on_border = False
                    break

            if all_on_border:
                frames.append({'color': color, 'top': min_r, 'bottom': max_r, 'left': min_c, 'right': max_c})

    return frames

def transform_grid(grid):
    result = [row[:] for row in grid]
    for f in find_rectangular_frames(grid):
        color = f['color']
        fill_val = 7 if color % 2 == 1 else 2
        for r in range(f['top']+1, f['bottom']):
            for c in range(f['left']+1, f['right']):
                result[r][c] = fill_val
    return result

