def find_frames_from_components(components):
    frames = []
    for c in components:
        # Check if the bounding box edge forms a complete frame
        color = c['color']
        top, bottom = c['min_r'], c['max_r']
        left, right = c['min_c'], c['max_c']

        # Verify all border cells have this color
        is_frame = True

        # Top row
        for col in range(left, right+1):
            if c['cells'].contains((top, col)):
                pass  # OK
            else:
                is_frame = False; break

        # Bottom row
        if is_frame:
            for col in range(left, right+1):
                if (bottom, col) not in c['cells']:
                    is_frame = False; break

        # Left column
        if is_frame:
            for row in range(top+1, bottom):
                if (row, left) not in c['cells']:
                    is_frame = False; break

        # Right column
        if is_frame:
            for row in range(top+1, bottom):
                if (row, right) not in c['cells']:
                    is_frame = False; break

        if is_frame and bottom - top >= 2 and right - left >= 2:
            frames.append({
                'color': color,
                'top': top, 'bottom': bottom,
                'left': left, 'right': right
            })

    return frames

# Fix set.contains bug
def is_frame(c):
    color = c['color']
    top, bottom = c['min_r'], c['max_r']
    left, right = c['min_c'], c['max_c']

    # Create lookup for O(1) access
    cells_set = set(c['cells'])

    # Check all border cells
    for r, c_row in [(top, range(left, right+1)), (bottom, range(left, right+1))]:
        if c_row == range(left, right+1):
            pass  # Already handled
        for cc in range(left, right+1):
            if (r, cc) not in cells_set:
                return False

    for r in range(top+1, bottom):
        if (r, left) not in cells_set or (r, right) not in cells_set:
            return False

    return bottom - top >= 2 and right - left >= 2

