# Find frames: for each color, check if its bounding box border is complete
def find_frames(grid):
    h, w = len(grid), len(grid[0])
    frames = []

    # Get all unique colors
    for row in grid:
        for cell in row:
            pass

    visited_rects = set()

    for c_val in range(10):  # Colors 0-9
        # Find bounding box of this color
        positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == c_val]
        if not positions:
            continue

        min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
        min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)

        # Must have interior (so size >= 3x3)
        if max_r - min_r < 2 or max_c - min_c < 2:
            continue

        # Check if border is complete
        ok = True

        # Top edge
        for col in range(min_c, max_c + 1):
            if grid[min_r][col] != c_val:
                ok = False; break

        if not ok:
            continue

        # Bottom edge
        for col in range(min_c, max_c + 1):
            if grid[max_r][col] != c_val:
                ok = False; break

        if not ok:
            continue

        # Left edge (excluding corners already checked)
        for row in range(min_r + 1, max_r):
            if grid[row][min_c] != c_val:
                ok = False; break

        if not ok:
            continue

        # Right edge (excluding corners)
        for row in range(min_r + 1, max_r):
            if grid[row][max_c] != c_val:
                ok = False; break

        if ok:
            key = (c_val, min_r, max_r, min_c, max_c)
            if key not in visited_rects:
                visited_rects.add(key)
                frames.append({
                    'color': c_val,
                    'top': min_r, 'bottom': max_r,
                    'left': min_c, 'right': max_c
                })

    return frames

